drop policy if exists scenes_member_select on public.scenes;
create policy scenes_member_select on public.scenes for select to authenticated using (exists (select 1 from public.campaign_members m where m.campaign_id = scenes.campaign_id and m.user_id = auth.uid()) or exists (select 1 from public.campaigns c where c.id = scenes.campaign_id and c.owner_id = auth.uid()));
drop policy if exists scenes_gm_write on public.scenes;
create policy scenes_gm_write on public.scenes for all to authenticated using (exists (select 1 from public.campaigns c where c.id = scenes.campaign_id and c.owner_id = auth.uid()) or exists (select 1 from public.campaign_members m where m.campaign_id = scenes.campaign_id and m.user_id = auth.uid() and m.role = 'gm')) with check (exists (select 1 from public.campaigns c where c.id = scenes.campaign_id and c.owner_id = auth.uid()) or exists (select 1 from public.campaign_members m where m.campaign_id = scenes.campaign_id and m.user_id = auth.uid() and m.role = 'gm'));
